  void StyleWorkspace(){Color teal=Color.FromArgb(31,79,184),ink=Color.FromArgb(23,58,143),line=Color.FromArgb(214,224,242);BackColor=Color.White;foreach(var b in new[]{scan,pause,cancel,prepare,clean,elevate,backups,export,selectFiles,selectVisibleFiles,all,clear}){b.FlatStyle=FlatStyle.Flat;b.Cursor=Cursors.Hand;b.FlatAppearance.BorderColor=line;b.BackColor=Color.White;b.ForeColor=ink;b.Margin=new Padding(0,6,8,0);}scan.BackColor=teal;scan.ForeColor=Color.White;scan.FlatAppearance.BorderColor=teal;prepare.FlatAppearance.BorderColor=teal;if(files.Columns.Count>1)files.Columns[1].HeaderText="逻辑大小 ↓";var host=status.Parent as TableLayoutPanel;if(host!=null){host.Controls.Remove(status);var row=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,Margin=Padding.Empty};row.RowStyles.Add(new RowStyle(SizeType.Absolute,16));row.RowStyles.Add(new RowStyle(SizeType.Percent,100));activity.Dock=DockStyle.Fill;activity.Style=ProgressBarStyle.Marquee;activity.MarqueeAnimationSpeed=0;activity.Visible=false;activity.Margin=new Padding(0,2,0,0);status.Dock=DockStyle.Fill;status.TextAlign=ContentAlignment.MiddleLeft;row.Controls.Add(activity,0,0);row.Controls.Add(status,0,1);host.Controls.Add(row,0,7);}var menu=new ContextMenuStrip();var copy=new ToolStripMenuItem("复制路径");var open=new ToolStripMenuItem("打开所在位置");copy.Click+=delegate{CopyCurrentFilePath();};open.Click+=delegate{OpenCurrentFile();};menu.Items.Add(copy);menu.Items.Add(open);files.ContextMenuStrip=menu;files.CellDoubleClick+=delegate(object s,DataGridViewCellEventArgs e){if(e.RowIndex>=0&&e.ColumnIndex!=0)OpenCurrentFile();};files.KeyDown+=delegate(object s,KeyEventArgs e){if(e.Control&&e.KeyCode==Keys.C){CopyCurrentFilePath();e.Handled=true;}};}
  void CopyCurrentFilePath(){if(files.CurrentCell==null)return;int row=files.CurrentCell.RowIndex;if(row<0||row>=visibleFiles.Length)return;try{Clipboard.SetText(visibleFiles[row].Path);}catch(Exception ex){status.Text="无法复制路径："+ex.Message;}}
  void OpenCurrentFile(){if(files.CurrentCell==null)return;int row=files.CurrentCell.RowIndex;if(row<0||row>=visibleFiles.Length)return;string path=visibleFiles[row].Path;try{if(String.IsNullOrEmpty(path)||!path.StartsWith(@"C:\",StringComparison.OrdinalIgnoreCase)){status.Text="只能打开 C 盘上的文件位置。";return;}Process.Start(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"explorer.exe"),"/select,\""+path+"\"");}catch(Exception ex){status.Text="无法打开文件位置："+ex.Message;}}
  static bool IsCache(string id){string text=id.ToLowerInvariant();return (text.Contains("cache")||text.Contains("temporary")||text=="system.tmp")&&!new[]{"password","cookie","history","credential","session","web_storage","installer"}.Any(text.Contains);}
  static void ConfigureGrid(DataGridView grid){grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.BackgroundColor=Color.White;grid.BorderStyle=BorderStyle.None;grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersHeight=34;grid.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.DisableResizing;grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(232,239,248);grid.ColumnHeadersDefaultCellStyle.ForeColor=Color.FromArgb(40,62,86);grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(219,234,251);grid.DefaultCellStyle.SelectionForeColor=Color.FromArgb(25,43,65);grid.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(248,250,253);grid.GridColor=Color.FromArgb(232,237,243);grid.CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal;grid.RowTemplate.Height=28;}
  void RuleValue(object sender,DataGridViewCellValueEventArgs e){if(e.RowIndex<0||e.RowIndex>=visibleRules.Count)return;var option=visibleRules[e.RowIndex];StructuredRuleStats stat;stats.TryGetValue(option.Id,out stat);switch(e.ColumnIndex){case 0:e.Value=selected.Contains(option.Id);break;case 1:e.Value=CleanupPresentation.Category(option.Id);break;case 2:e.Value=CleanupPresentation.Name(option);break;case 3:e.Value=stat==null?"未扫描":Display.Size(stat.Bytes);break;case 4:e.Value=stat==null?"未知":stat.Files.ToString("N0");break;case 5:e.Value=stat==null?"未知":stat.SpecialOperations+" / "+stat.UnsupportedOperations+" / "+stat.UnknownOperations;break;case 6:e.Value=CleanupPresentation.Impact(option.Id);break;}}
  void FileValue(object sender,DataGridViewCellValueEventArgs e){if(e.RowIndex<0||e.RowIndex>=visibleFiles.Length)return;var file=visibleFiles[e.RowIndex];switch(e.ColumnIndex){case 0:e.Value=IsFileSelected(file);break;case 1:e.Value=Display.Size(file.Bytes);break;case 2:e.Value=plan!=null?(plan.Kind(file)=="Delete"?"删除":"截断"):fileSelectionMode&&selectedFiles.ContainsKey(file.Identity)?(selectedFiles[file.Identity]=="Delete"?"删除":"截断"):String.Join(" / ",file.Actions.Select(a=>a.Kind=="Delete"?"删除":"截断").Distinct());break;case 3:e.Value=file.Path;break;case 4:e.Value=String.Join(", ",file.Actions.Select(a=>a.RuleId).Distinct());break;case 5:e.Value=file.Executable?"执行前再次校验":"仅统计 / 跳过";break;}}
  bool IsFileSelected(StructuredFile file){return fileSelectionMode?selectedFiles.ContainsKey(file.Identity):file.Actions.Any(a=>selected.Contains(a.RuleId));}
  StructuredFile[] ChosenFiles(){return result==null?new StructuredFile[0]:result.Files.Where(IsFileSelected).ToArray();}
  void EnterFileMode(){if(fileSelectionMode)return;var chosen=ChosenFiles();selectedFiles.Clear();fileActionChoices.Clear();foreach(var file in chosen.Where(f=>f.Executable)){string kind=file.Actions.Any(a=>selected.Contains(a.RuleId)&&a.Kind=="Delete")?"Delete":"Truncate";selectedFiles.Add(file.Identity,kind);fileActionChoices.Add(file.Identity,kind);}selected.Clear();fileSelectionMode=true;}
  void AddFileSelection(StructuredFile file){string kind;if(!fileActionChoices.TryGetValue(file.Identity,out kind)){kind=file.Actions.Any(a=>a.Kind=="Delete")?"Delete":"Truncate";fileActionChoices.Add(file.Identity,kind);}selectedFiles.Add(file.Identity,kind);}
  void FileClicked(object sender,DataGridViewCellEventArgs e){if(busy||e.ColumnIndex!=0||e.RowIndex<0||e.RowIndex>=visibleFiles.Length)return;var file=visibleFiles[e.RowIndex];if(!file.Executable){status.Text="该文件仅用于统计，不能勾选处理。";return;}EnterFileMode();if(selectedFiles.ContainsKey(file.Identity))selectedFiles.Remove(file.Identity);else AddFileSelection(file);InvalidatePlan();rules.Invalidate();files.Invalidate();UpdateSelection();status.Text="已切换到逐文件选择；不连带执行注册表或特殊动作，请重新预览。";}
  internal void SelectAllFiles(bool onlyVisible){if(busy||result==null)return;var candidates=onlyVisible?visibleFiles:result.Files;EnterFileMode();if(!onlyVisible){selectedFiles.Clear();fileActionChoices.Clear();}foreach(var file in candidates.Where(f=>f.Executable))if(!selectedFiles.ContainsKey(file.Identity))AddFileSelection(file);InvalidatePlan();rules.Invalidate();files.Invalidate();UpdateSelection();tabs.SelectedIndex=1;status.Text=onlyVisible?"已勾选当前显示的可处理文件；筛选之外已有的勾选保留。":"已勾选全部可处理文件；仅统计/未知项目和特殊动作不会连带执行。";}
  void FilterRules(){string text=search.Text.Trim();visibleRules=catalog.Where(o=>text.Length==0||(CleanupPresentation.Category(o.Id)+CleanupPresentation.Name(o)+o.Id).IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0).OrderByDescending(o=>stats.ContainsKey(o.Id)?stats[o.Id].Bytes:0).ToList();rules.RowCount=visibleRules.Count;rules.Invalidate();}
  void FilterFiles(string rule){string text=search.Text.Trim();visibleFiles=result==null?new StructuredFile[0]:(plan==null?result.Files:plan.Files).Where(f=>(rule==null||f.Actions.Any(a=>a.RuleId==rule))&&(text.Length==0||f.Path.IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0||f.Actions.Any(a=>a.RuleId.IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0))).OrderByDescending(f=>f.Bytes).ToArray();files.RowCount=visibleFiles.Length;files.Invalidate();}
  void InvalidatePlan(){plan=null;clean.Enabled=false;RefreshCleanButton();files.Invalidate();}
  void RefreshCleanButton(){clean.BackColor=clean.Enabled?Color.FromArgb(140,72,36):Color.White;clean.ForeColor=clean.Enabled?Color.White:Color.FromArgb(33,55,50);clean.FlatAppearance.BorderColor=clean.Enabled?Color.FromArgb(140,72,36):Color.FromArgb(208,218,230);}
  int SelectedUnknown(){return fileSelectionMode?0:selected.Where(id=>stats.ContainsKey(id)).Sum(id=>stats[id].UnknownOperations);}
  void UpdateSelection(){var chosen=ChosenFiles();var special=result==null||fileSelectionMode?new StructuredSpecial[0]:result.Specials.Where(s=>selected.Contains(s.RuleId)).ToArray();selectedSummary.Text="已选文件："+CleanupCapacity.Files(chosen.Sum(f=>f.Bytes),chosen.LongLength)+" · "+(fileSelectionMode?"仅文件":selected.Count+"条规则")+" · 特殊动作 "+special.Length+"\r\n"+(chosen.Length==0&&special.Length==0?"未选择，不会删除。":backupFiles.Checked?"文件备份保留在C盘，继续占用空间。":"文件内容永久处理；规则设置动作先备份。")+" 全局诊断 "+(result==null?0:result.Diagnostics.Length)+"，未知范围不计作保证释放量。";}
  void SetBusy(bool value,bool mutation){busy=value;mutating=mutation;activity.Visible=value;activity.MarqueeAnimationSpeed=value?28:0;scan.Enabled=prepare.Enabled=all.Enabled=clear.Enabled=selectFiles.Enabled=selectVisibleFiles.Enabled=elevate.Enabled=backups.Enabled=search.Enabled=backupFiles.Enabled=freshHashes.Enabled=!value;rules.Enabled=files.Enabled=!value;clean.Enabled=!value&&plan!=null;export.Enabled=!value&&result!=null;pause.Enabled=value&&!mutation;cancel.Enabled=value;cancel.Text=mutation?"取消后续项目":"取消扫描";RefreshCleanButton();var changed=WorkingChanged;if(changed!=null)changed();}
  internal bool HasPreparedPlan{get{return plan!=null;}}internal int SelectedRuleCount{get{return selected.Count;}}internal int SelectedFileCount{get{return ChosenFiles().Length;}}
  internal void SelectRules(IEnumerable<string> ids){if(busy)throw new InvalidOperationException();fileSelectionMode=false;selectedFiles.Clear();selected.Clear();foreach(string id in ids){if(!catalog.Any(o=>o.Id==id))throw new ArgumentException("未知规则");selected.Add(id);}InvalidatePlan();FilterRules();UpdateSelection();}
  internal async Task ScanAll(){if(busy)return;InvalidatePlan();control=new StructuredScanControl();cancellation=new CancellationTokenSource();watch=Stopwatch.StartNew();SetBusy(true,false);timer.Start();status.Text="读取目录并建立去重文件清单；首次扫描会计算内容指纹。";try{if(catalog.Length==0)catalog=await Task.Run(()=>engine.List(cancellation.Token));bool forceFresh=freshHashes.Checked;var values=await Task.Run(()=>engine.Scan(catalog.Select(o=>o.Id),control,cancellation.Token,p=>{lock(progressGate)latest=p;},forceFresh));result=values;selected.Clear();selectedFiles.Clear();fileSelectionMode=false;stats.Clear();foreach(var option in catalog)stats[option.Id]=result.Stats(option.Id);FilterRules();FilterFiles(null);if(embedded)tabs.SelectedIndex=1;UpdateSelection();totals.Text="扫描文件总量："+CleanupCapacity.Files(result.LogicalBytes,result.FileCount)+"（身份去重）\r\n特殊动作 "+result.Specials.Length+" · 诊断 "+result.Diagnostics.Length+"；"+(result.Diagnostics.Length==0?"已计量当前可读文件，特殊动作大小未知。":"存在未知或跳过项目，不是保证可释放量。");log.Text=String.Join("\r\n",result.Diagnostics)+"\r\n\r\n特殊动作：\r\n"+String.Join("\r\n",result.Specials.Select(s=>s.RuleId+" | "+s.Kind+" | "+s.Path+" | "+(s.Executable?"可单独校验处理":"未支持，不会执行")+" | "+s.Detail));status.Text="扫描结束 · "+watch.Elapsed.TotalSeconds.ToString("0.0")+" 秒；选择后预览固定清单。";}catch(OperationCanceledException){status.Text="扫描已取消，本次结果不完整；没有开始清理。";totals.Text="本次扫描未完成；先前结果仅供参考。";}catch(Exception e){status.Text="扫描失败；没有开始清理。";log.Text=e.ToString();totals.Text="完整范围未知，不能作为可释放空间。";}finally{timer.Stop();lock(progressGate)latest=null;cancellation.Dispose();cancellation=null;control.Dispose();control=null;pause.Text="暂停";SetBusy(false,false);}}
  internal void PrepareSelection(){if(busy||result==null||(fileSelectionMode?selectedFiles.Count==0:selected.Count==0)){status.Text="请先勾选文件或规则；可使用“全选文件”。";return;}InvalidatePlan();try{plan=fileSelectionMode?engine.PreviewFiles(result,selectedFiles.Keys,backupFiles.Checked,selectedFiles):engine.Preview(result,selected,backupFiles.Checked);selectedSummary.Text="待清理文件："+CleanupCapacity.Files(plan.Bytes,plan.FileCount)+" · 特殊动作 "+plan.Specials.Length+"\r\n"+(plan.BackupFiles?"文件备份继续占用C盘。":"文件内容永久处理。")+" 所选未知/失败 "+SelectedUnknown()+" · 全局诊断 "+result.Diagnostics.Length+"；预览15分钟有效。";clean.Enabled=true;RefreshCleanButton();search.Text=String.Empty;FilterFiles(null);tabs.SelectedIndex=1;status.Text="请核对本次固定文件明细和容量，再确认清理。";}catch(Exception e){status.Text=e.Message;}}
  async Task ExecutePrepared(){if(busy||plan==null)return;var prepared=plan;string warning="本次已选文件："+CleanupCapacity.Files(prepared.Bytes,prepared.FileCount)+"。\r\n"+(prepared.BackupFiles?"文件内容备份到C盘，不保证释放空间。":"文件内容不备份，永久处理。")+"\r\n注册表设置先备份；不支持的动作会跳过。所选未知/失败 "+SelectedUnknown()+"，全局诊断 "+result.Diagnostics.Length+"；未知范围不代表可释放空间。\r\n\r\n"+String.Join("\r\n",prepared.Ids.Select(id=>id+"："+CleanupPresentation.Impact(id)+"\r\n"+catalog.Single(o=>o.Id==id).Warning))+"\r\n\r\n确认执行刚才预览的清单？";using(var confirmation=new FrozenCleanupConfirmation(warning,prepared)){if(confirmation.ShowDialog(this)!=DialogResult.OK)return;}plan=null;control=new StructuredScanControl();cancellation=new CancellationTokenSource();watch=Stopwatch.StartNew();SetBusy(true,true);timer.Start();try{var execution=await Task.Run(()=>engine.Execute(prepared,true,control,cancellation.Token,p=>{lock(progressGate)latest=p;}));timer.Stop();lock(progressGate)latest=null;log.Text=String.Join("\r\n",execution.Items.Select(item=>item.Status+" | "+item.Kind+" | "+item.Path+" | "+item.Detail+" | 备份="+item.BackupId));status.Text=(execution.Cancelled?"已取消后续项目":execution.Success?"所选操作完成":"存在跳过/失败，请核对日志")+" · 处理逻辑量 "+Display.Size(execution.CompletedBytes)+" · C盘可用空间观测变化 "+Display.Size(execution.FreeAfter-execution.FreeBefore)+"（含其他程序同期变化）";tabs.SelectedIndex=2;selected.Clear();selectedFiles.Clear();fileSelectionMode=false;rules.Invalidate();files.Invalidate();selectedSummary.Text="本次处理："+CleanupCapacity.Files(execution.CompletedBytes,execution.CompletedFiles)+"\r\nC盘可用空间观测变化："+CleanupCapacity.Describe(execution.FreeAfter-execution.FreeBefore)+"（含其他程序同期变化）；请重新扫描。";}catch(Exception e){log.Text=e.ToString();status.Text="执行未确认全部成功；可能已完成部分项目，备份与日志保留。";}finally{timer.Stop();lock(progressGate)latest=null;cancellation.Dispose();cancellation=null;control.Dispose();control=null;SetBusy(false,false);}}
  async Task Export(){if(result==null||busy)return;using(var dialog=new SaveFileDialog{Filter="JSON|*.json",FileName="CDriveCleaner-scan-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;await ExportTo(dialog.FileName);}}
  internal async Task ExportTo(string target){
   if(result==null||busy)return;var snapshot=result;SetBusy(true,true);cancel.Enabled=false;status.Text="正在导出当前完整文件明细；文件不会被清理。";
   try{string path=NativeFiles.Normalize(target);if(!SafetyPolicy.IsWithin(path,Environment.GetFolderPath(Environment.SpecialFolder.UserProfile)))throw new IOException("请保存到当前用户目录。");await Task.Run(()=>{using(var pins=new NativeFiles.ParentLocks(path))using(var stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.Read))using(var writer=new StreamWriter(stream,new UTF8Encoding(true))){var json=new JavaScriptSerializer();writer.Write("{\"Mode\":\"FrozenReadOnlyCatalog\",\"LogicalBytes\":"+snapshot.LogicalBytes+",\"Files\":[");bool first=true;foreach(var file in snapshot.Files){if(!first)writer.Write(',');first=false;writer.Write(json.Serialize(new{file.Path,file.Identity,file.Bytes,file.Executable,Rules=file.Actions.Select(a=>new{a.RuleId,a.Kind}).ToArray()}));}writer.Write("],\"Specials\":[");first=true;foreach(var item in snapshot.Specials){if(!first)writer.Write(',');first=false;writer.Write(json.Serialize(new{item.RuleId,item.Kind,item.Path,item.Detail,item.Executable}));}writer.Write("],\"Diagnostics\":[");first=true;foreach(string diagnostic in snapshot.Diagnostics){if(!first)writer.Write(',');first=false;writer.Write(json.Serialize(diagnostic));}writer.Write("]}");}});status.Text="已导出当前结果："+path+"；仍可核对已选清单后清理。";}
   catch(Exception e){status.Text="导出未完成："+e.Message;}
   finally{SetBusy(false,false);}
  }
 }
 internal sealed class StructuredBackupsForm:Form {
  bool restoring;readonly StructuredBackupStore store;readonly ListView list=new ListView();readonly Label status=new Label();readonly Button restore=new Button();
  internal StructuredBackupsForm(StructuredBackupStore source){store=source;Text="文件与设置备份 / 恢复";Size=new Size(1050,650);Font=new Font("Microsoft YaHei UI",9);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(15),RowCount=3,ColumnCount=1};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,60));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));Controls.Add(layout);layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="仅恢复本工具认证并校验的备份；已有文件或设置冲突时拒绝覆盖。备份仍占C盘空间。\r\n系统维护、驱动、还原点删除和软件卸载不属于文件恢复范围。"},0,0);list.Dock=DockStyle.Fill;list.View=View.Details;list.FullRowSelect=true;list.MultiSelect=false;list.Columns.Add("原位置",600);list.Columns.Add("类型 / 状态",180);list.Columns.Add("大小",100);layout.Controls.Add(list,0,1);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};restore.Text="恢复所选备份…";restore.AutoSize=true;status.AutoSize=true;actions.Controls.Add(restore);actions.Controls.Add(status);layout.Controls.Add(actions,0,2);Shown+=delegate{LoadBackups();};restore.Click+=async delegate{if(list.SelectedItems.Count!=1)return;var item=(StructuredBackupEntry)list.SelectedItems[0].Tag;if(MessageBox.Show(this,"恢复到原位置：\r\n"+item.OriginalPath+"\r\n已有内容时不覆盖。","确认恢复",MessageBoxButtons.OKCancel,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.OK)return;restoring=true;restore.Enabled=false;string message="";try{bool ok=await Task.Run(()=>store.Restore(item.Id,out message));status.Text=(ok?"恢复完成：":"未恢复：")+message;LoadBackups();}catch(Exception e){status.Text=e.Message;}finally{restoring=false;restore.Enabled=true;}};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(restoring){e.Cancel=true;status.Text="正在恢复当前文件/设置，请等待完成后关闭。";}};}
  void LoadBackups(){list.Items.Clear();try{foreach(var item in store.List())list.Items.Add(new ListViewItem(new[]{item.OriginalPath??item.Error,item.Kind+" / "+item.State,Display.Size(item.Bytes)}){Tag=item});}catch(Exception e){status.Text=e.Message;}}
 }
